// Generated by scripts/build-behavior-changes.ts from behavior-changes.d/ and the CHANGELOG markers; do not edit.
// Regenerate: bun scripts/build-behavior-changes.ts (the release does it). Docs: behavior-changes.d/README.md

/** The plain-text rows of behavior-changes.d/, each dated by the release whose CHANGELOG section marks it. */
export const RELEASED_BEHAVIOR_CHANGES: ReadonlyArray<{ since: string; id: string; text: string }> = [
  { since: '0.60.706.0', id: 'db_wins_unimported_gst2579', text: "A database-wins file-drift repair no longer overwrites a newer change to the file that sync has not imported. `gbrain repair file-drift --prefer database` by `--held` or `--all-drifted` now lists such a page `kept_newer_file` (a file edited since the last import) or `kept_newer_delete` (a file another writer deleted) and leaves it held; naming the page with `--slug` previews it and names the commit it would discard (sha, author, date). Every file-drift apply now asks for the user's consent, so a script that applies without `--yes` exits 3. `gbrain sources reconcile --apply` refuses `source_changed` when its result takes the database copy over such an edit. A database copy newer than the file (the file still holds what sync imported, or gbrain's own write of a revision the page has since moved past) repairs as before; gbrain's own writer commit of a revision the database never took counts as newer. The keep_db policy is unchanged." },
  { since: '0.60.708.0', id: 'extract_receipt_sealed_7620', text: "An extraction run's receipt page (type `extract_receipt`, under `extracts/`) is now chunked and sealed in the transaction that writes it. Remote/MCP `search` and `query` on the extracted source no longer report `safe_index_pending` or `projection_pending` after every extraction, doctor `safe_index_pending` no longer counts new receipts, and remote readers can now find receipts like other generated pages (demoted in ranking). Receipts an earlier release wrote stay unsealed until `gbrain repair safe-chunks --apply`. A receipt is database-only bookkeeping on every brain, with or without a Git repository: when its slug already holds a content page or a page with a file in Git, the receipt is not written (the extraction logs a warning and carries on) instead of overwriting that page." },
  { since: '0.60.708.0', id: 'commit_push_dry_run_checks_paths', text: "`gbrain git commit-push --dry-run` now asks git about the planned paths the way the real run stages them, and runs the real run's checks before staging, so it exits 1 with the real run's code and text where that run would refuse (`commit_outside_source_root` for a path outside `gbrain.sourceRoot` unless `--allow-outside-source-root` is passed, `commit_prestaged_paths`, and `commit_paths_invalid` for a path outside a sparse-checkout definition or one that matches nothing) instead of exiting 0 and listing it. It still takes no lock and writes nothing." },
  { since: '0.60.708.0', id: 'schema_client_behind_7776', text: "A gbrain binary older than the brain's schema (the database's schema version is above its newest migration because a newer gbrain on another host or install migrated it) now refuses schema setup with `client_behind` and changes nothing: `gbrain init` and `init --migrate-only`, the schema step of `gbrain upgrade`, and `gbrain apply-migrations` (before any orchestrator runs, and before the schema pass of `--force-schema` or `--force-all`; `--list` and `--dry-run` still work). Before, it replayed its own older schema, which reinstalled superseded function bodies (the writer-fence guards among them) over the newer ones, and reported success. Reads and ordinary commands on the older binary are unchanged; the fix is `gbrain upgrade` on that host. A new doctor check, `schema_function_bodies`, fails when a function of this gbrain's schema has another body installed (what an older replay leaves behind) and names each one: upgrade every gbrain that shares the database, then run `gbrain init --migrate-only`. PGLite and Postgres alike, with or without a git repo." },
  { since: '0.60.708.0', id: 'purge_keeps_outcome_markers_7831', text: "Purging a fact whose text is exactly `EXTRACTION_COMPLETE` or `EXTRACTION_NOT_APPLICABLE` (`gbrain forget <id> --purge`) no longer removes the conversation-facts outcome rows that carry the same text: the purge, its receipt, `--status` and a restore replay leave them in place, so those pages are not extracted again. The purged claim itself is still removed and tombstoned." },
  { since: '0.60.708.0', id: 'audit_secrets_glued_marker_8034', text: "`gbrain transcripts audit-secrets` and re-scans of stored pages again report a password glued to an importer redaction marker by punctuation (`<REDACTED:user-pattern>,<password>`, `<REDACTED:x>.<password>`): punctuation after a marker ends it only when a space or the line end follows. Pages that hold such a line show up as affected again; import-time redaction is unchanged." },
  { since: '0.60.708.0', id: 'fence_locators_skip_code_8020', text: "A fence marker written inside markdown code (an inline `code` span or a fenced code block) no longer counts as a fence for concept republication, the Google connector's fence carry, `gbrain repair connector-fences` or `gbrain repair take-supersession`, matching how the fence readers already read the page. Pages that quote a marker in code are no longer held `concept_preservation_hold` or `connector_fence_below_timeline`, or skipped as unparsed, for that reason alone." },
  { since: '0.60.708.0', id: 'ghost_code_page_recorded_file_7967', text: "`gbrain repair ghost-pages` on a managed brain now retires a code or image page (a JSON, YAML or image file indexed as a page) at its recorded file instead of at `<slug>.md` (#7967): when that file is restored after the request was prepared, publication refuses and the page is kept (outcome `file_restored`), and the door commits the removal of the recorded file, so on a git-canonical source HEAD stops holding the file of a page the database deleted." },
  { since: '0.60.708.0', id: 'derived_write_through_retry_8092', text: "The dream cycle's atom and concept write-through (#8092) waits for a busy checkout commit lock without freezing the worker (up to 30 s, as before). After a refused commit, a rewrite of an existing atom or concept file and the removal of a retired atom's file are now retried on the next run like new files, instead of staying behind the database until the page changes again; the summary reads \"N file(s) rolled back; the next run writes them again\". The rollback runs under the commit lock and takes its files out of the pending write-through ledger, so a later hand edit at one of those paths is never swept into a gbrain commit; when the lock stays busy the files are left for that writer's commit." },
  { since: '0.60.708.0', id: 'owner_repair_file_restore_7960', text: "On an unmanaged repository brain, `gbrain repair provenance --apply` or `gbrain trust backfill --repair-unknown-markers` whose database write fails after the page file was written now puts the file's previous bytes back, and when the write had been committed on a hardened checkout, commits that restore (`gbrain: restore write-through <slug>`), so a failed apply leaves the file, Git and the database unchanged (#7960)." },
  { since: '0.60.708.0', id: 'protocol_guard_refusal_typed_7777', text: "A write refused during publication by a persistence protocol guard (SQLSTATE 42501) now fails with the guard's own code on its receipt, `writer_upgrade_required`, `writer_not_quiesced`, `unsupported_mutation_protocol` or `writer_coordinator_required` (relationship `unreadable_state` when the database role cannot read the writer state), with `write_error_detail` naming the guard and a suggestion for that refusal, instead of `storage_error` for an unexpected owner exception. `gbrain sources writer status` gives the same step in `recent_failures[].next_action`. Any other permission error is unchanged, and so is the same refusal outside publication (write admission, protocol activation), which still reports `permission_denied`. Every `unreadable_state` refusal (#7780) now reads \"writer state this database role cannot fully read (row-level security hides it or applies to the role, or a singleton row is missing)\", its receipt suggests running gbrain as a role that can read that state instead of upgrading, and `gbrain sources writer status` shows the table in `recent_failures[].error_detail.state`." },
  { since: '0.60.708.0', id: 'door_index_refresh_7717', text: "On a source with `canonical: git`, a page committed with a legacy file mode (100664) no longer gets a mode-only commit when a write leaves its bytes unchanged, and with `core.fileMode=false` a write of it commits the page as 100644 (before, Git refused the rebuilt tree and the write failed `git_unavailable`). A write replayed after its commit landed and refused `git_index_conflict` because someone staged the page meanwhile now says HEAD already holds its bytes, instead of that it committed nothing. The index refresh after a door commit removes the index copies (`index.gbrain-<pid>-*` in the git directory) a killed gbrain process left behind, and on Windows retries a briefly refused rename of the index before it reports that the commit landed but the index was not updated." },
  { since: '0.60.708.0', id: 'stored_root_predicate_7646', text: "Stored paths (`sources.local_path`, `sync.repo_path`) are judged absolute by one rule in sync, `config set sync.repo_path`, write-through, `gbrain sources set-path --clear` and doctor. On Windows only a drive path (`C:\\...`) or a UNC share counts: a root-relative `\\brain` or `/brain`, which names a folder on whatever drive gbrain runs from, is refused by sync (`sync_anchor_relative`) and cleared by `--clear` like `.`. Doctor's `default_source_local_path` now warns when the `default` source's own path is absolute only on another operating system (a Windows drive path read on Linux or macOS), where it reported ok. A page or fact write whose stored root is not absolute on this host records the database-only reason `relative_root` (it was `no_repo_configured` or none)." },
  { since: '0.60.708.0', id: 'sync_anchor_relative_jobs_7646', text: "A queued `sync` job for a source whose stored path is not absolute on this host completes as a skip (`reason: sync_anchor_relative`, with the ask-the-user fix) instead of failing and using up its attempts. `gbrain sync --all --json` gives such a source's entry `code`, `why` and `fix` beside `error`. With a stored `.`, `gbrain sync --repo ./` is refused like `--repo .`. A relative `sync.repo_path` behind a `default` source with no path no longer lets an explicit `--repo` advance default's last synced commit. `gbrain dream --json` puts a failed phase's ask-the-user fix in its `cycle_failed` envelope." },
  { since: '0.60.708.0', id: 'conversion_root_owner_7956', text: "`gbrain sources canonical <id> --to git` refuses a registered root it cannot read (gone, unmounted, a file, no permission or a symlink loop) with `source_root_unreadable` (reason and fix) instead of a raw filesystem or Git error, and an archived or re-registered source refuses `owner_unavailable` before the Git checkout check instead of `git_checkout_required`. An apply whose source was returned to mixed (`--to mixed`) while it ran reports `incomplete` with a message that the source is mixed, never `converted` (#7956)." },
  { since: '0.60.708.0', id: 'stuck_recovery_strict_followup_7715', text: "On a git-canonical (strict) source, `gbrain repair stuck-recovery --keep disk` now says the kept bytes are an uncommitted edit at the file's path and hands off to commit then sync (`gbrain git commit-push --path <checkout> -m \"<message>\" -- <path>`, or `git -C <checkout> restore -- <path>` to discard, then `gbrain sync --source <id> --no-pull`; verify with `git status --porcelain` then `gbrain sync status --source <id> --json`), with an ask-the-user `fix` in the item detail, instead of a database-side `sources reconcile`. Mixed sources keep the reconcile follow-up (#7715)." },
  { since: '0.60.708.0', id: 'url_clone_fences_held_preview_7910', text: "`gbrain repair url-clone-fences` lists a held file (for example `visibility_noncanonical`) once, as an apply item, and no longer also counts it as a residual; its preview says the restored file equals HEAD, so sync does not screen it again and the page changes once an upstream fix is pulled and synced (it no longer claims sync holds the file) (#7910)." },
  { since: '0.60.708.0', id: 'streamed_put_visibility_wording_7881', text: "On a brain without managed persistence, `gbrain put --file` and `gbrain capture --file` of a page over the single-string ceiling that asks for `visibility: private` in a spelling page privacy does not read refuse `visibility_not_applied` with the page-write message a smaller put gives (nothing was written; write `visibility: private` on its own frontmatter line), not the import hold's \"sync or import the file again\" (#7881)." },
  { since: '0.60.708.0', id: 'git_durability_refusal_no_side_effects_7634', text: "`gbrain sources writer git-durability <source>` without `--dry-run` now checks `--admin-intent writer_git_durability` and `--expected-state` first: a missing, wrong or stale approval refuses (`writer_admin_intent_required` or `writer_admin_state_changed`) before the token file is read and before anything changes. It used to rewrite the durability block in `AGENTS.md`/`RESOLVER.md`, wire the `--pat-file` credential and retry parked pushes first. After an approved apply, `agents.commit` now names `gbrain git commit-push --path <root> -m \"<msg>\" -- <file>` instead of plain git." },
  { since: '0.60.708.0', id: 'parked_push_hidden_page_7110', text: "`gbrain sources writer retry-effects <source> --parked-pushes` (and `git-durability --pat-file`) no longer stops the whole run when one parked request's remote writer can no longer see its page (it became private): that request is listed in `refused` with its `request_id`, code `page_not_found`, the page slug and a read-only receipt command, the other parked pushes are retried, and the run ends `partial` (exit 1). The refused request stays parked; nothing retries it under another authority." },
  { since: '0.60.708.0', id: 'embedding_preflight_abort_7772', text: "An embedding effect whose stop signal fires while its provider call is being admitted (for example a one-shot `gbrain put` exiting) is now retried (`queued`, `embedding_aborted`) instead of failing for good as `embedding_budget_refused`, which blocked writer quiescence and showed in doctor `stale_embedding_effects` until `gbrain repair embedding-effects --apply`. A real budget refusal still fails as `embedding_budget_refused`." },
  { since: '0.60.708.0', id: 'mirror_read_only_legacy_writers_7098', text: "On a brain without managed persistence, a source marked `gbrain sources mirror-readonly` is now left untouched by the legacy disk writers below (#7098): `sync --full` no longer re-exports never-committed database pages into its checkout, `brainstorm --save`, page write-through, timeline entries and fact fences keep the write in the database (write-through and timeline report `skipped: mirror_read_only`), `forget` expires a fenced fact in the database without rewriting the file, and the extract cycle neither fences its database-only facts into the file nor counts them in its legacy-row guard. An owner trust repair (`gbrain repair provenance`, `trust backfill`) lists such a page `needs_review` with detail `mirror_read_only` instead of rewriting its file. The dream cycle leaves such a checkout alone too: its reverse-written synthesis, patterns and cycle-summary pages stay in the database (#8935). Before, only managed publication honored the flag, so these writers gave the mirror local changes that could stop its `git pull --ff-only`." },
  { since: '0.60.708.0', id: 'copied_root_fix_names_self_transfer_7671', text: "A managed write refused `recovery_required` because a source's checkout is a new directory at its recorded path (a copied or restored brain, detail `physical_root_directory_changed`) now carries the relocated-root self-transfer as its `fix` (#7671): `gbrain sources writer transfer prepare <source> --self-transfer --confirm-relocated-root` with its admin intent, then the accept as `fix.then`, a host-admin step (`next: tell_user_to_run`), on a put_page receipt too, where `fix` used to point at the write receipt. Nothing is re-stamped automatically; the write still refuses until the self-transfer runs." },
  { since: '0.60.708.0', id: 'door_landed_replay_gst2517', text: "On a source configured `canonical: git`, a write whose door commit landed in Git and whose database transaction then failed before committing (an owner exception after the commit) is now replayed by its owner instead of ending `failed` / `storage_error`: the replay finds its change already committed and records it without a second commit. A `forget` caught there now records its withdrawal, so the fact turns inactive and remembering the same claim is refused `fact_withdrawn`; before, the fact stayed active until a sync, no withdrawal was recorded (so the claim could be remembered again) and the reply said nothing was saved. A replay that fails as well ends failed with the commit named on its receipt (`landed_before_row`), and a `remember` or `forget` reply then names that commit instead of saying nothing was saved. `gbrain repair failed-writes` lists a refused `forget` as a caller write to resubmit instead of one the next dream cycle produces again." },
  { since: '0.60.708.0', id: 'requester_scope_gst363', text: "On a brain that serves several people (two or more enabled members, or config `access.serves = several`; a brain pinned `access.serves one` never does), a remote read through a connection bound to no member (an access token, an OAuth client, or a stdio server with no member binding) is now refused with `requester_scope_required` before any work; `whoami`, `get_brain_identity`, `get_status_snapshot`, `search_modes`, `get_health` and a non-admin key's own `get_job` / `wait_job` still answer. A connection that existed when the brain started serving several people (config `access.serves_since`, set once, or this upgrade) reads for 14 more days with `_meta.access.requester_scope` naming the date and the fix; one created later is refused at once. Bind each connection to the person it serves: `gbrain auth rescope --token <name>|--client <id> --member <id>`; a stdio harness only one person uses, `gbrain setup claude-code|codex --stdio-member <id>`; a harness several people talk to, one `--member` key per person over `gbrain serve --http`. A shared agent names the person per call (`--may-act-for`), and `--reads-unscoped --yes` marks one credential to read unscoped on purpose. `gbrain auth create` and `gbrain auth register-client` refuse an unbound credential on such a brain (`credential_scope_required`); `gbrain doctor` fails `unscoped_shared_reads` per unbound credential and `gbrain post-upgrade` lists them. `gbrain doctor` also fails `shared_stdio_binding` when `mcp.stdio_member` is set on a host where OpenClaw or Hermes is installed and the brain serves several people; a `hermes` on PATH counts as Hermes only when it is a script. Hosted brains set `access.requester_scope_enforce false`, which turns every refusal into the notice. Member-bound credentials (the owner's included), attested calls, a one-person brain and the local CLI see no change; writes are not affected." },
  { since: '0.60.710.0', id: 'writer_fence_fail_closed_7636', text: "Since v0.60.474.0 (#7636, migration v278), a Postgres role that row-level security hides gbrain's writer state from (the `persistence_brain` row; on a managed brain also the `git_canonical_brain` row, a source row while any source is Git-canonical, or the page behind a tag, timeline entry or take) is refused with `writer_coordinator_required` (relationship `unreadable_state`) on every guarded write, unmanaged brains included, where such writes used to pass as unmanaged. Run gbrain as the table owner, a role that bypasses RLS, or a scoped role whose policies cover those rows (docs/ENGINES.md#writer-protocol-fences)." },
  { since: '0.60.711.0', id: 'propose_takes_rejected_memory_7299', text: "The dream cycle's `propose_takes` phase no longer puts a claim back in the review queue after you rejected the same claim text on the same page (#7299). Before, any edit to the page re-extracted it and the rejected claims came back as new proposals. A reworded claim is still proposed; the run reports how many it dropped as `rejected_claims_skipped`." },
  { since: '0.60.711.0', id: 'grade_takes_auto_resolve_7542', text: "`gbrain config set cycle.grade_takes.auto_resolve.enabled true` now does what it documents (#7542): the dream cycle's `grade_takes` phase applies a verdict with confidence 0.95 or higher (3/3 at 0.85 or higher on the ensemble path) to the take. Before, the key was ignored and every verdict stayed review-only. Unset or false is unchanged: verdicts wait for review in `gbrain takes grades`." },
  { since: '0.60.711.0', id: 'dream_write_deferral_w3', text: "A dream purge or consolidate write that was accepted but is still pending after its publish wait no longer fails the phase: the phase warns `dream_write_deferred` with the receipt id, and the next pass reads that receipt before it submits anything for the source (committed clears it; a failure is reported with its real code). After 3 passes still pending, doctor `dream_write_deferred` warns with `gbrain write-request -- <id>`. `gbrain config set dream.write_deferral.enabled false` restores the failing phase." },
  { since: '0.60.711.0', id: 'synthesize_no_candidates_w3', text: "A dream synthesize window where every transcript is already synthesized now returns before triage, the manifest context and the child queue, with `details.reason: no_candidates` and the cooldown stamped. Synthesize deaths also count per transcript under `dream:synth-v2:@file:<source>:<file>` once they span two content keys, so a transcript that grows between dying runs is refused after 3 deaths in 24 hours like any other key, and `gbrain dream reset-key` now accepts every key `--list` prints, `dream:phase:` keys included." },
  { since: '0.60.711.0', id: 'embedding_restamp_w3', text: "The maintenance cycle's embed phase now first stamps the current embedding signature on pages whose every chunk already holds a current-model vector, up to 500 pages a run, with no provider call; a page edited or re-embedded during the stamp is left for the next run. Three failed runs in a row warn as doctor `embedding_restamp_stalled`. `gbrain config set embed.restamp.enabled false` turns it off. Health's embedding coverage now counts live pages only, so chunks kept on a soft-deleted page no longer lower it." },
  { since: '0.60.711.0', id: 'doctor_foreign_skills_folder', text: "`gbrain doctor` no longer grades a skills folder it found by walking up from the current directory unless gbrain installed it (a skills.lock.json, a valid manifest.json or the skillpack block in its resolver file): resolver_health and skill_currency report \"not a gbrain skills folder (<path>)\" as info, so an agent's own skills folder no longer lowers health_score or fails doctor. Pass --skills-dir (or set GBRAIN_SKILLS_DIR / OPENCLAW_WORKSPACE) to grade it as before. Agent crons should page on the new `gbrain doctor --alert` (exit 17 act, 18 unknown), not on health_score." },
  { since: '0.60.711.0', id: 'upgrade_installs_no_autopilot', text: "An upgrade no longer installs autopilot on a Postgres brain that has none, even with sync.repo_path set: the v0.11.0 migration's Phase F is skipped (reason not_installed), prints the install command and records it, and `gbrain doctor` shows it as a minions_migration line until you run it. An autopilot already installed for the brain is reinstalled as before." },
  { since: '0.60.711.0', id: 'session_lane_budget_gbra133', text: "New read-only `gbrain doctor` check `session_lane_budget` counts this database role's connections across every gbrain process (by process kind and host, from the `gbrain <kind>:<pid>:<nonce>` connection name) and warns at 80% of the limit, naming the kinds holding the most. Behind a Supabase pooler, set `GBRAIN_SESSION_LANE_LIMIT` to the project's `pool_size` to compare (Postgres cannot read it); without it the check reports the counts only. Without a pooler the limit is `max_connections` less the reserved slots. Not applicable on PGLite." },
  { since: '0.60.711.0', id: 'github_item_webhook_backlog_8799', text: "A GitHub webhook for an item event (issue, pull request, comment, review, check) now answers HTTP 429 `webhook_backlog_full` with `Retry-After: 30` when 50 item jobs are already waiting for that source and none of them covers the event; it used to answer 202 with another item's job while the event was dropped. GitHub does not redeliver a 429 on its own: redeliver it from the webhook's Recent Deliveries, or let the next sweep or `gbrain sync --source <id>` catch it." },
  { since: '0.60.711.0', id: 'webhook_capture_no_default_fallback_gst2113', text: "A webhook capture (`POST /ingest` and its `ingest_capture` job) whose credential's write source is archived, unregistered or removed before the capture lands now fails the job with `source_changed` (`detail: webhook_source_unavailable`) and writes nothing. Before, it was written under `default`, a source the credential may not be granted, and could replace a page there. Restore the source and run `gbrain jobs retry` on the job. Captures that do not come from a webhook keep the `default` fallback." },
  { since: '0.60.711.0', id: 'code_rechunk_module_elixir_8128', text: "Code sync re-chunks TypeScript, TSX, JavaScript, Python, Ruby and Elixir files once (a per-language chunker revision): top-level code with no named definition (anonymous default exports, top-level `if`/`for`/`try`, Python's `__main__` block) becomes `<file>::__module__` chunks with call edges, and Elixir modules and functions become named definitions that `code-def` and `code-callers` find. The sync cost gate prices only those files." },
  { since: '0.60.711.0', id: 'db_link_child_folder_6983', text: "On the DB link path (`gbrain extract links --source db` and automatic link backfills), a `.md` link with a folder and no `./` or `../` prefix (`[x](notes/a.md)`) now resolves against the linking page's folder first, then its parent folders, then the brain root, matching `--source fs`. Where both a child page and a root page exist, the edge now points at the child." },
  { since: '0.60.711.0', id: 'remote_think_host_model_gbra437', text: "A remote `think` (MCP, HTTP or a thin client) now runs on the brain host's think model (`models.think`, then `models.default`) unless the host lists the requested `model` in the new `think.remote_models` key (comma-separated, empty by default). An unlisted model, or a listed one the host cannot run, no longer fails the call with the explicit-model error: the host model answers, `warnings` carries `MODEL_OVERRIDE_IGNORED:not_allowed` or `:unusable`, and the result carries a `model_override_ignored` notice. Remote `rounds` runs one round. The local CLI `--model` is unchanged, and a keyless brain answers as before." },
  { since: '0.60.711.0', id: 'physical_root_moved_8625', text: "On a managed brain, a checkout moved to a new path (or whose parent folder was renamed) is now named: `gbrain sources add`, `gbrain sources set-path` and `gbrain sources writer claim` refuse with `recovery_required`, detail `physical_root_moved`, naming the recorded path, the worktree and the commands that bring it back, instead of a generic identity error (add, claim) or detail-less `source_checkout_missing` (set-path). Their `--dry-run` now refuses as the real run does: before, the add, claim and set-path dry runs of a moved checkout, the add and claim dry runs of a folder holding a copied ownership stamp, and the set-path dry run of a missing checkout exited 0. Nothing about ownership changed; the dry runs still write nothing." },
  { since: '0.60.712.0', id: 'moved_pages_fold_gst2584', text: "gbrain repair file-drift --held no longer offers a delete or a recreate for a page whose file moved while its deletion was held: it lists the page as moved_to <slug> with the new gbrain repair moved-pages --source <id> --slug <old-slug> fold command, and --prefer file skips it. A file that names the page type gbrain-base 1.0.0 gave its path, equal to the type copy an older gbrain stored in the page's frontmatter, now keeps the type a later schema pack gave the page on import, and the import records the rename as a legacy_type retype stamp; before, the next edit read the old type back into the page." },
  { since: '0.60.712.0', id: 'folder_holding_page_gst2492', text: "On a source whose pages are canonical in Git (`canonical: git`), a fact for an entity with no page under a folder access rule is no longer kept in the database only: it is held on the holding page of the entity's folder (`partners/memory/unattributed` for `partners/acme-example`), in Git (or database-only where the folder is) with exactly the readers the entity's page would have. The reply names that `page`. `gbrain access rule add` previews the held facts a new rule covers (`held_facts_moving`) and its apply moves them off their holding page (`held_facts`), as do `gbrain access apply`, `gbrain access resume` and a sync that applies a rule from Git; the moved rows and those entities' struck rows also leave that page's saved versions in the database (`held_versions_editing`, `held_versions_edited`), and Git history is not rewritten. A saved version stored in segments is not edited: the preview names how many (`segmented_versions_not_edited`) and the apply says `complete: false`. A move still pending is reported with its request id (`pending`, `HELD_FACT_PENDING`), not counted as moved. A held fact is now also hidden from a caller who cannot read its holding page, even under a rule with `covers_derived: false`. `gbrain repair facts-home` writes such facts to their folder's page and lists as `folder_restricted` only an exact page rule or unreadable rules. A `remember` for a page-less entity under an exact page rule now refuses `git_home_required` with a fix that creates the page, and one whose access rules this database role cannot read refuses `access_policy_pending`; both wrote the fact to the database before. An existing page whose slug ends in `/memory/unattributed` is now read as a holding page: a row with no `entity` cell becomes a fact with no entity, a row naming an entity in the page's own folder becomes that entity's held fact, and a row naming an entity of another folder is a fence problem. Non-strict sources and brains with no Git repository are unchanged." },
  { since: '0.60.713.0', id: 'stuck_head_released_9227', text: "On a PGLite brain, the next gbrain process that opens the brain now releases at once every write claim an earlier, exited process left running and runs those writes again, instead of leaving later writes to the same source pending for the rest of the claim's lease (30 s, or about 6 minutes while publishing). `gbrain sources writer status` reports a claim whose owner has provably exited (that case on PGLite, a dead process on the same machine on Postgres) with `owner_exited: true`, `resumes_on_its_own: true`, `owner_live: false` and `next.code: claim_owner_exited`, where it said `claim_running`." },
  { since: '0.60.713.0', id: 'receipt_git_state_live_9227', text: "A write receipt read after the write (`gbrain write-request`, `get_write_request`, `list_write_requests`) for a page on a checkout that is not `canonical: git` now takes `persistence.git_state` from the page's Git effect: `committed` with the commit in `persistence.git_commit`, or `superseded`, `skipped`, `failed` or `retrying` with `persistence.git_reason`, where it always said `queued`. Stored receipts are not rewritten; the stored `outcome` still says `queued`." },
  { since: '0.60.713.0', id: 'label_repairs_hold_refusals_gst2603', text: "gbrain repair visibility and gbrain repair private-labels now ignore stamps gbrain keeps only in the database (a pack-renamed type, the validate: false grandfather stamp, a legacy_type retype record) when they edit a page's label line, so those pages are labelled. A page whose file still differs in a real key, or whose label line cannot be edited as one line, is held by the preview with the blocking key and its next step and is left out of the approved set. A page that starts refusing after the preview is declined with label_edit_refused, nothing is written for it, the run exits 0 and it no longer counts toward item_failures_systemic. Their previews, and those of gbrain access rule add and import, also list same-slug pages in other sources that the change leaves readable (open_twins), with their count and the command that covers them; nothing changes those pages for you." },
  { since: '0.60.713.0', id: 'corpus_segmented_entity_9279', text: "Captured session files whose facts name a large entity page (one stored in segments, over about 1 MiB) are now extracted: facts inferred from a mention of that page were refused after the model call, so those files were retried five times and then stopped. The first sweep after this upgrade retries each file stopped that way once, at the cost of one model call per stopped window, with no command needed. From now on a refusal that retrying cannot change stops its window after one paid attempt instead of five, retention keeps the session file instead of deleting it at the un-ingested limit, and gbrain doctor (memory_writeback) counts these files as held. gbrain sweep --retry-failed --apply still retries them by hand." },
  { since: '0.60.715.0', id: 'skillpack_update_untouched', text: "Installed skills can now take gbrain's current version whole when you never edited them. `gbrain skillpack scaffold` (including `--harness` installs) and every update record the sha256 of each skill file it installed in `~/.gbrain/skillpack-state.json` (schema `gbrain-skillpack-state-v2`; an older gbrain refuses that file instead of dropping its records). Preview what would change with `gbrain skillpack reference --all --update-untouched --dry-run`; a skill with any edited file, a pinned skill (`gbrain skillpack pin <skill>`) or one with no recorded hash is skipped with a reason and a diff. Every update is journaled under `~/.gbrain/skillpack-backups/` and undone with `gbrain skillpack restore <id>`. `gbrain upgrade` writes no skill files; nothing runs on upgrade." },
  { since: '0.60.715.0', id: 'claude_cli_setting_sources_8342', text: "On Claude Code 2.1.314 or newer, the claude-cli provider now runs its child with `--setting-sources \"\"`, so your own `~/.claude/CLAUDE.md`, memory and `settings.json` no longer steer gbrain's background claude-cli calls. The subscription login is kept, but `settings.json`'s `env`, `apiKeyHelper` and permission rules no longer reach the child either. `GBRAIN_CLAUDE_CLI_USER_SETTINGS=1` (shell or ~/.gbrain/.env) loads them again. Older CLIs are unchanged." },
  { since: '0.60.715.0', id: 'unattended_maintenance_doctor_gbra438', text: "`gbrain doctor` has a new check, `unattended_maintenance`, which reads the free-upkeep record `maintenance.last_run`: it warns (and so can lower doctor status from healthy) when no upkeep run is recorded on a brain older than 48 hours, when the last run is older than 48 hours, or when one step failed three runs in a row; the fix is `gbrain maintain --unattended`. Upkeep turned off (`maintenance.auto false`) or owned by an autopilot reads ok. New commands: `gbrain maintain --unattended`, `--status` and `--purge` (preview, then `--yes --expect <hash>`)." },
  { since: '0.60.715.0', id: 'bookkeeping_gc_phase_gbra438', text: "The dream cycle has a new phase, `bookkeeping_gc`, after `purge`: it now does the retention GC that `purge` used to do (op checkpoints, brainstorm checkpoints, batch-retry audit files, volunteer events, decision receipts, applied captures, retrieval feedback), with the same retentions. `gbrain dream --json` reports those counts under `bookkeeping_gc` instead of `purge`, whose details keep only sources, pages and orphan clones; `--phase purge` no longer runs the GC." },
  { since: '0.60.715.0', id: 'autopilot_refusals_structured_gbra438', text: "`gbrain autopilot --install` refusals (a PGLite brain without --force, no repo path) now go through the agent error contract: codes `autopilot_pglite_daemon` and `autopilot_no_repo`, a why, a fix and `--json` output, instead of a bare line on stderr; PGLite and repo-less users are pointed to `gbrain maintain --status`." },
  { since: '0.60.715.0', id: 'cycle_skip_text_gbra438', text: "A dream cycle phase skipped for want of a checkout no longer says (postgres/remote engine), which was wrong on PGLite: the summary is now: requires a local brain directory; this brain has no on-disk checkout; pass --dir <path> to run filesystem phases. The reason code `no_brain_dir` is unchanged." },
  { since: '0.60.715.0', id: 'cycle_freshness_keyless_consent_gbra438', text: "On a brain with no chat or embedding key, the `cycle_freshness` doctor fix (`gbrain dream --source <id>`) now asks no paid consent (`consent: []`, so `next: run`), because no phase it runs can spend." },
  { since: '0.60.715.0', id: 'serve_idle_upkeep_gbra438', text: "An open `gbrain serve` (stdio or HTTP) now runs the free unattended upkeep (`gbrain maintain --unattended`: link and timeline extraction, stale-page checks, free repair lanes, bookkeeping GC, and on a keyed brain the capped embedding step) while it is idle, at most once every 24 hours per brain, in slices of about 3 seconds that stop when a tool call arrives. It never deletes a page. `maintenance.auto false` or `GBRAIN_SWEEP=0` turns it off; an autopilot brain is left to autopilot. The record it writes is `maintenance.last_run` with runner `serve`." },
  { since: '0.60.715.0', id: 'serve_http_idle_timer_gbra438', text: "HTTP `gbrain serve --http` now has an idle timer: it counts an MCP POST as foreground work and runs the idle upkeep only when no request is in flight, aborting the upkeep slice when one arrives. Before, only the stdio server had idle work." },
  { since: '0.60.715.0', id: 'init_upkeep_line_gbra438', text: "The first-run settings block printed by `gbrain init` and `gbrain setup <harness>` (and its `--json` decisions) now includes an `upkeep` decision when it shows other settings: upkeep runs while an agent has `gbrain serve` open and idle, on by default, turned off with `gbrain config set maintenance.auto false`. New commands: `gbrain maintain --schedule` (opt-in launchd, systemd or cron job every 6 hours, preview with `--dry-run`, asks consent) and `--unschedule`." },
  { since: '0.60.716.0', id: 'chronicle_events_trust_cap_9284', text: "Legacy Life Chronicle event pages (captured_via: life-chronicle:auto) are now capped at agent_written and at the tier of their depth page when gbrain trust claim-sources lifts a source, so they no longer read as your own notes; rows a claim already lifted change only when you run gbrain trust claim-sources --relower (preview with gbrain trust claim-sources --relower --dry-run first, and add --source <id> for a source whose claim has ended), and gbrain doctor counts them." },
  { since: '0.60.716.0', id: 'audit_secrets_escaped_encoded_8265', text: "The opt-in high-entropy assignment detector now also catches a credential whose key quote is escaped (`{\\\"password\\\":\\\"…\\\"}`, JSON inside a JSON string, with up to three backslashes) and one after a URL-encoded separator (`password%3D…`, `token%3A…`). The value stops before an escaped closing quote and, after an encoded separator, before the next `%26` parameter; a URL-encoded URL value is treated as a reference, not a secret. `gbrain doctor` asks once for a fresh `gbrain transcripts audit-secrets` run: it is read-only, makes no model or network call, and on a 5 MB synthetic transcript took about a third of a second. Transcripts imported from now on redact both shapes. Pages imported before are not rewritten; the audit lists the ones that hold such a line as affected." },
  { since: '0.60.717.0', id: 'holding_page_versions_gst2497', text: "A holding page (memory/unattributed, or a folder's <folder>/memory/unattributed) now keeps only its newest five saved versions, whatever their size, as large pages already did. `get_versions` and `gbrain revert` see only those five. Every fact row on the page is kept, the page itself still holds every row, and Git keeps every state of the page where the brain has a repository. An older holding page sheds its extra versions in batches of at most 100 on its next saves, so nothing runs on upgrade. Once a version is removed, an `as_of` read of the page reports incomplete history, and `gbrain repair unwithdrawn-facts` lists that page's candidates as ambiguous: restore them with `--include-ambiguous` and the hash of that preview. Nothing to run." },
  { since: '0.60.717.0', id: 'owner_room_marks_gst2639', text: "A harness can now declare the group chat an answer goes into (the X-Gbrain-Room header, request-level _meta.room, or a room tool argument once whoami shows features.room). The caller's read is unchanged; every page and fact in the answer is marked room_access with whether the people in that chat could have read it, and the room_above_level notice tells the agent to keep those items out of the reply. A call with no room is unaffected. With mcp.strict_params set to reject, every tool schema now also declares the optional room argument. See docs/guides/rooms.md." },
  { since: '0.60.718.0', id: 'managed_push_scan_every_publish_gst2650', text: "Every push gbrain makes is now scanned for secrets with no opt-out: `commitAndPush` no longer has an unscanned mode, so a push handed over from a busy publish lock is scanned too. Only the commits the remote lacks are read, and a missing remote-tracking branch is fetched first instead of scanning the whole history. In a managed root below the repository's top level, a commit changing that root's own `.gbrain-scan-allow` is held like one at the top level, and its path globs match paths relative to that root. A strict (canonical: git) source's commit whose files a Git clean filter changed is scanned instead of trusted, and so is one made before this release that is still unpushed; either is still pushed when the scan finds nothing. Git replace refs no longer change what a page-write commit holds. A false positive in an unpushed commit holds the push with `publish_secret_found` naming the file, line and rule, never the value: add its fingerprint to `.gbrain-scan-allow`, then run `gbrain sources writer retry-effects <source> --parked-pushes`, or the push fix `gbrain doctor` names." },
  { since: '0.60.718.0', id: 'strict_fallback_refusal_gst2635', text: "On a source whose pages are canonical in Git (`canonical: git`), a fact the Google loops extraction (or any writer that keeps a fallback entity, writeSingleFact) finds for an entity with no page that an exact page rule names is now refused `git_home_required` (reason `facts_lane`) before anything is stored, with a fix that creates the entity's page; before, it was stored in the database only, with no file in Git, or refused with a message naming memory/unattributed. When the access rules cannot be read the write refuses `access_policy_pending` (retry), and that refusal's message now names the entity, for `remember` too. The loops job still records the loop and logs the refusal code with the entity's page; nothing is stored for that fact. Facts stored the old way are not changed: `gbrain repair facts-home` lists them as `folder_restricted`. Sources that are not strict and brains with no Git repository are unchanged." },
  { since: '0.60.719.0', id: 'access_first_import_history_gst2638', text: "A folder-rule edit (gbrain access rule add, rm, revert or import) on a git-backed source that has no folder-rule revision yet now refuses before writing anything, with access_policy_history_unreadable, when its checkout is shallow or a partial clone missing the Git objects of its folder-rule history; it used to commit the file and leave the whole source reading as nobody. When you hit it, run git -C <source root> fetch --unshallow (for a partial clone, git -C <source root> log --first-parent -p HEAD -- .gbrain/access.yml, which fetches every version), then rerun the same gbrain access rule command; nothing was written, so the source keeps its current reads meanwhile. A first edit on a source with no folder-rule history no longer reads the whole source as nobody while it applies. An edit whose result state is invalid now exits 1 instead of 0. Unchanged: a plain gbrain sync of a shallow checkout whose commits already hold folder-rule history still fails closed as before, reading the whole source as nobody because the history cannot be replayed; recover the same way, git -C <source root> fetch --unshallow, then gbrain sync --source <id> --no-pull." },
  { since: '0.60.719.0', id: 'room_cli_think_writes_gst2639', text: "`--room <list>` now works on every gbrain operation command (`gbrain query \"plan\" --room alice-example,group:team-a`). The command prints what it always printed; the room only adds marks. With --json every item carries room_access and the document carries _meta.room, and a list answer becomes { results, _meta } only when --room is given. Without --json, stderr adds a [gbrain room: ...] summary. The local CLI marks the brain owner's view (gbrain access owner set) or the member --as names; with no owner every item is unknown (unbound). A trailing --room with no value marks every item unknown (invalid) with the degraded stamp and exits 0. A running gbrain serve that owns a PGLite brain marks delegated answers, and a thin client sends the room as _meta.room; an owner or host that predates room marks leaves every item unknown (not_supported). With a room declared, think answers are now marked at the strictest class of everything their synthesis retrieved (unknown when built partly from takes or with no recorded evidence), and put_page and remember mark the page or fact they wrote without a degraded stamp, where before they answered op_not_covered. Calls with no room are unchanged. Guide: docs/guides/rooms.md." },
  { since: '0.60.719.0', id: 'owner_turn_sends_templates_gst2656', text: "New installs get two changed templates. The access-policy template's group-chat rule now says a turn the owner sends, verified by sender identity, is done at the owner's scope exactly as in a private chat, written for the room, with truly private material offered in the owner's private chat and never a refusal; every other member is answered at the group's level, and a member saying the owner wants something is making their own ask. The agent template's red line on messaging third parties now says a send the principal asks for in their own verified message (or through a delegate the principal set up and the host authenticates) goes out as asked, in any chat and to any recipient, with no approval phrase and no draft-first step; the agent still never messages anyone as the principal on its own initiative, and a request another person quotes, forwards or relays is that person's. The money and deletion red lines are unchanged. Existing installs keep their own ACCESS_POLICY.md and AGENTS.md; to adopt the new wording, copy it from templates/ACCESS_POLICY.md.template and templates/bootstrap/template-repo/AGENTS.md." },
  { since: '0.60.720.0', id: 'storage_shelf_stored_object_type_8894', text: "The bundled `gbrain-base-v2` schema pack (the `init` default, also inherited by `company-brain`) is now version 1.6.0 and declares the `stored-object` page type the storage verbs stamp on every storage shelf card, so registering, adopting or importing a card no longer prints a `page_type_undeclared` notice, doctor `schema_pack_consistency` does not warn about the shelf, and `unify-types` never retypes cards to `note`. Existing pages keep their type; no data changes. The active pack identity reads `gbrain-base-v2@1.6.0+<hash>`." },
  { since: '0.60.721.0', id: 'derived_origin_carry_private_gst2689', text: "Deleting a page that keeps other pages private now writes a visibility: private label on each page that was private only because of it (a summary whose derived_from names it, an atom extracted from it, a synthesized concept built from such an atom), before the deleted page's row is removed. On a brain with Git the derived page's file gains that one label line. The label stays if you restore the deleted page later. If a label cannot be written, the purge keeps the deleted page soft-deleted and gbrain doctor reports it as derived_origin_parked with the page that blocks it; an explicit gbrain delete --purge then returns purge_held instead of purging." },
];

